// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Local creative agents (legacy) — empty until G12
	// (GET /api/agents/)
	ListLegacyAgents(ctx context.Context, request ListLegacyAgentsRequestObject) (ListLegacyAgentsResponseObject, error)
	// Local agent categories (legacy) — empty until G12
	// (GET /api/agents/categories/)
	ListLegacyAgentCategories(ctx context.Context, request ListLegacyAgentCategoriesRequestObject) (ListLegacyAgentCategoriesResponseObject, error)
	// Skill catalog (legacy) — empty until G12
	// (GET /api/apps/skills/)
	ListSkills(ctx context.Context, request ListSkillsRequestObject) (ListSkillsResponseObject, error)
	// Local username/password login (transition window)
	// (POST /api/auth/login/)
	AuthLogin(ctx context.Context, request AuthLoginRequestObject) (AuthLoginResponseObject, error)
	// Logout; clears the studio_session cookie
	// (POST /api/auth/logout/)
	AuthLogout(ctx context.Context, request AuthLogoutRequestObject) (AuthLogoutResponseObject, error)
	// Current user profile
	// (GET /api/auth/me/)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Update current user profile
	// (PATCH /api/auth/me/)
	PatchMe(ctx context.Context, request PatchMeRequestObject) (PatchMeResponseObject, error)
	// Local account registration (password stored Argon2id)
	// (POST /api/auth/register/)
	AuthRegister(ctx context.Context, request AuthRegisterRequestObject) (AuthRegisterResponseObject, error)
	// Rotate a JWT refresh token (transition window)
	// (POST /api/auth/token/refresh/)
	TokenRefresh(ctx context.Context, request TokenRefreshRequestObject) (TokenRefreshResponseObject, error)
	// Conversation list for the history sidebar (newest first)
	// (GET /api/conversations/)
	ListConversations(ctx context.Context, request ListConversationsRequestObject) (ListConversationsResponseObject, error)
	// Conversation detail with messages (history replay + deep-link resolve)
	// (GET /api/conversations/{conversationId}/)
	GetConversation(ctx context.Context, request GetConversationRequestObject) (GetConversationResponseObject, error)
	// Delete the conversation's messages (keep the conversation)
	// (DELETE /api/conversations/{conversationId}/clear/)
	ClearConversation(ctx context.Context, request ClearConversationRequestObject) (ClearConversationResponseObject, error)
	// Delete a conversation and its messages/runs (owner only)
	// (DELETE /api/conversations/{conversationId}/delete_conversation/)
	DeleteConversation(ctx context.Context, request DeleteConversationRequestObject) (DeleteConversationResponseObject, error)
	// Local admin login (Argon2id password)
	// (POST /api/identity/admin/login)
	AdminLogin(ctx context.Context, request AdminLoginRequestObject) (AdminLoginResponseObject, error)
	// Exchange the OAuth ?code&state for a studio session
	// (GET /api/identity/oauth/exchange)
	OauthExchange(ctx context.Context, request OauthExchangeRequestObject) (OauthExchangeResponseObject, error)
	// Redirect (302) the browser to the Feishu OAuth authorize page
	// (GET /api/identity/oauth/start)
	OauthStart(ctx context.Context, request OauthStartRequestObject) (OauthStartResponseObject, error)
	// Current session user (cookie-authenticated)
	// (GET /api/identity/session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)
	// List openable applications (bare array, no pagination envelope)
	// (GET /api/v2/applications)
	ListApplications(ctx context.Context, request ListApplicationsRequestObject) (ListApplicationsResponseObject, error)
	// Create an application (admin only — agent marketplace "new Aily agent")
	// (POST /api/v2/applications)
	CreateApplication(ctx context.Context, request CreateApplicationRequestObject) (CreateApplicationResponseObject, error)
	// Delete an application (409 when referenced by conversations/runs)
	// (DELETE /api/v2/applications/{id})
	DeleteApplication(ctx context.Context, request DeleteApplicationRequestObject) (DeleteApplicationResponseObject, error)
	// Application detail (compact shape)
	// (GET /api/v2/applications/{id})
	GetApplication(ctx context.Context, request GetApplicationRequestObject) (GetApplicationResponseObject, error)
	// Update an application / rebind runtime (creator or staff)
	// (PATCH /api/v2/applications/{id})
	UpdateApplication(ctx context.Context, request UpdateApplicationRequestObject) (UpdateApplicationResponseObject, error)
	// Pre-run attachment upload (stored in studio storage; the worker uploads to the provider with the user's UAT)
	// (POST /api/v2/applications/{id}/attachments)
	UploadApplicationAttachment(ctx context.Context, request UploadApplicationAttachmentRequestObject) (UploadApplicationAttachmentResponseObject, error)
	// Clear avatar (falls back to emoji icon)
	// (DELETE /api/v2/applications/{id}/avatar)
	ClearApplicationAvatar(ctx context.Context, request ClearApplicationAvatarRequestObject) (ClearApplicationAvatarResponseObject, error)
	// Stream avatar image bytes
	// (GET /api/v2/applications/{id}/avatar)
	GetApplicationAvatar(ctx context.Context, request GetApplicationAvatarRequestObject) (GetApplicationAvatarResponseObject, error)
	// Replace avatar (multipart file; png/jpg/jpeg/gif/webp ≤ 2MB)
	// (POST /api/v2/applications/{id}/avatar)
	UploadApplicationAvatar(ctx context.Context, request UploadApplicationAvatarRequestObject) (UploadApplicationAvatarResponseObject, error)
	// Unset workspace main agent
	// (DELETE /api/v2/applications/{id}/default-agent)
	UnsetDefaultAgent(ctx context.Context, request UnsetDefaultAgentRequestObject) (UnsetDefaultAgentResponseObject, error)
	// Set as workspace main agent (chat + enabled binding only)
	// (POST /api/v2/applications/{id}/default-agent)
	SetDefaultAgent(ctx context.Context, request SetDefaultAgentRequestObject) (SetDefaultAgentResponseObject, error)
	// Unpin application (idempotent)
	// (DELETE /api/v2/applications/{id}/favorite)
	UnfavoriteApplication(ctx context.Context, request UnfavoriteApplicationRequestObject) (UnfavoriteApplicationResponseObject, error)
	// Pin application (idempotent)
	// (POST /api/v2/applications/{id}/favorite)
	FavoriteApplication(ctx context.Context, request FavoriteApplicationRequestObject) (FavoriteApplicationResponseObject, error)
	// Resolve artifact URL (24h cache refresh) and 302 to the provider URL
	// (GET /api/v2/artifacts/{artifactId}/open)
	OpenArtifact(ctx context.Context, request OpenArtifactRequestObject) (OpenArtifactResponseObject, error)
	// Runs of a conversation (newest first, owner only)
	// (GET /api/v2/conversations/{conversationId}/runs)
	ListConversationRuns(ctx context.Context, request ListConversationRunsRequestObject) (ListConversationRunsResponseObject, error)
	// Create a read-only share snapshot of selected messages (owner only)
	// (POST /api/v2/conversations/{conversationId}/shares)
	CreateConversationShare(ctx context.Context, request CreateConversationShareRequestObject) (CreateConversationShareResponseObject, error)
	// Revoke a share (owner only); public links stop resolving immediately
	// (DELETE /api/v2/conversations/{conversationId}/shares/{shareToken})
	RevokeConversationShare(ctx context.Context, request RevokeConversationShareRequestObject) (RevokeConversationShareResponseObject, error)
	// Deliver a share snapshot card to Feishu users/groups (owner only)
	// (POST /api/v2/feishu/forward)
	ForwardShareToFeishu(ctx context.Context, request ForwardShareToFeishuRequestObject) (ForwardShareToFeishuResponseObject, error)
	// Feishu forward targets (contacts or groups) for the caller
	// (GET /api/v2/feishu/forward/targets)
	ListFeishuForwardTargets(ctx context.Context, request ListFeishuForwardTargetsRequestObject) (ListFeishuForwardTargetsResponseObject, error)
	// Public read-only share payload (no authentication)
	// (GET /api/v2/public/shares/{shareToken})
	GetPublicShare(ctx context.Context, request GetPublicShareRequestObject) (GetPublicShareResponseObject, error)
	// Resolve an artifact of a share snapshot (no authentication) and 302 to the provider URL
	// (GET /api/v2/public/shares/{shareToken}/artifacts/{artifactId}/open)
	OpenPublicShareArtifact(ctx context.Context, request OpenPublicShareArtifactRequestObject) (OpenPublicShareArtifactResponseObject, error)
	// Create a run (lazily creates the conversation when conversation_id is absent)
	// (POST /api/v2/runs)
	CreateRun(ctx context.Context, request CreateRunRequestObject) (CreateRunResponseObject, error)
	// Run detail (owner or staff only; unknown ids return 404)
	// (GET /api/v2/runs/{runId})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// Artifacts of a run (created_at ascending)
	// (GET /api/v2/runs/{runId}/artifacts)
	ListRunArtifacts(ctx context.Context, request ListRunArtifactsRequestObject) (ListRunArtifactsResponseObject, error)
	// Attach a file to a queued run
	// (POST /api/v2/runs/{runId}/attachments)
	UploadRunAttachment(ctx context.Context, request UploadRunAttachmentRequestObject) (UploadRunAttachmentResponseObject, error)
	// Issue a run command (cancel / respond / resume)
	// (POST /api/v2/runs/{runId}/commands)
	CreateRunCommand(ctx context.Context, request CreateRunCommandRequestObject) (CreateRunCommandResponseObject, error)
	// One keyset page of persisted run events (replay after reconnect)
	// (GET /api/v2/runs/{runId}/events)
	ListRunEvents(ctx context.Context, request ListRunEventsRequestObject) (ListRunEventsResponseObject, error)
	// SSE stream (paged DB replay from the durable cursor, then Redis live frames)
	// (GET /api/v2/runs/{runId}/stream)
	StreamRun(ctx context.Context, request StreamRunRequestObject) (StreamRunResponseObject, error)
	// Runtime catalog (active providers × registered adapters)
	// (GET /api/v2/runtimes)
	ListRuntimes(ctx context.Context, request ListRuntimesRequestObject) (ListRuntimesResponseObject, error)
	// Validate resource id format + remote visibility (best-effort)
	// (POST /api/v2/runtimes/validate)
	ValidateRuntime(ctx context.Context, request ValidateRuntimeRequestObject) (ValidateRuntimeResponseObject, error)
	// List the caller's schedules (keyset pagination)
	// (GET /api/v2/schedules)
	ListSchedules(ctx context.Context, request ListSchedulesRequestObject) (ListSchedulesResponseObject, error)
	// Create a schedule (owner = caller; enabled by default)
	// (POST /api/v2/schedules)
	CreateSchedule(ctx context.Context, request CreateScheduleRequestObject) (CreateScheduleResponseObject, error)
	// Compute the next trigger times for a candidate trigger (no side effects)
	// (POST /api/v2/schedules/preview)
	PreviewScheduleRuns(ctx context.Context, request PreviewScheduleRunsRequestObject) (PreviewScheduleRunsResponseObject, error)
	// Delete a schedule (occurrence/run/delivery history is kept)
	// (DELETE /api/v2/schedules/{id})
	DeleteSchedule(ctx context.Context, request DeleteScheduleRequestObject) (DeleteScheduleResponseObject, error)
	// Schedule detail
	// (GET /api/v2/schedules/{id})
	GetSchedule(ctx context.Context, request GetScheduleRequestObject) (GetScheduleResponseObject, error)
	// Update a schedule (next_run_at recomputed from now)
	// (PATCH /api/v2/schedules/{id})
	UpdateSchedule(ctx context.Context, request UpdateScheduleRequestObject) (UpdateScheduleResponseObject, error)
	// Disable a schedule (no new occurrences; already queued runs are kept)
	// (POST /api/v2/schedules/{id}/disable)
	DisableSchedule(ctx context.Context, request DisableScheduleRequestObject) (DisableScheduleResponseObject, error)
	// Enable a schedule (next_run_at recomputed from now; missed slots are not replayed)
	// (POST /api/v2/schedules/{id}/enable)
	EnableSchedule(ctx context.Context, request EnableScheduleRequestObject) (EnableScheduleResponseObject, error)
	// Execution history (keyset pagination, newest first)
	// (GET /api/v2/schedules/{id}/occurrences)
	ListScheduleOccurrences(ctx context.Context, request ListScheduleOccurrencesRequestObject) (ListScheduleOccurrencesResponseObject, error)
	// Trigger one real occurrence now (overlap policy applies; next_run_at untouched)
	// (POST /api/v2/schedules/{id}/run-now)
	RunScheduleNow(ctx context.Context, request RunScheduleNowRequestObject) (RunScheduleNowResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

